import {AxiosResponse} from 'axios';
import {Request, Response} from 'express';
import {IAxiosError} from '../interfaces/global';
import Setting, {ISettingModel} from '../models/setting.model';
import api from '../services/api';
import logger from '../services/logger';

class DnsController {

  constructor() {
    this.login = this.login.bind(this);
  }

  public async login(req: Request, res: Response) {
    const {username, password} = req.body;
    if (username && password && username.length) {
      logger.info(`username ${username}`);
      try {
        const domain = await this.findDomainByUser(username);
        logger.info(`domain ${domain}`);
        api.login(`${domain}/api/1.1/users/login/`, {
          username,
          password
        }).then((response: AxiosResponse) => {
          const {data, status} = response.data;
          data.domain = domain;
          res.json({
            status,
            data
          });
        }).catch((err: IAxiosError) => {
          const {status, error} = err.response ? err.response.data : {status: 500, error: ''};
          // logger.error( err.response ? error : '');
          res.status(status || 500).json({
            status: status || 500,
            error: err.response ? error : ''
          });
        });
      } catch (e) {
        logger.error(e);
      }
    } else {
      logger.info('Username and password are required');
      res.status(401).json({
        status: 401,
        error: 'Username and password are required'
      });
    }
  }

  private findDomainByUser(username: string): Promise<string> {
    return new Promise((resolve, reject) => {
      const defaulDomain = 'https://www.osacontrol.com';
      this.findByEqual(username)
        .then((setting) => {
          if (setting) {
            resolve(setting.equal[0].domain);
          } else if (username.includes('@')) {
            this.findByContain(username.split('@')[1])
              .then((setting) => {
                if (setting) {
                  resolve(setting.contain[0].domain);
                } else {
                  resolve(defaulDomain);
                }
              })
              .catch((error) => {
                logger.error(error);
                reject(error);
              });
          } else {
            resolve(defaulDomain);
          }
        })
        .catch((error) => {
          logger.error(error);
          reject(error);
        });
    });
  }

  private findByEqual(username: string): Promise<ISettingModel> {
    return new Promise((resolve, reject) => {
      Setting.findOne({'equal.text': username}, {'equal.$.domain': 1}, (err, setting: ISettingModel) => {
        if (err) {
          reject(err);
        }
        resolve(setting);
      });
    });
  }

  private findByContain(domain: string): Promise<ISettingModel> {
    return new Promise((resolve, reject) => {
      Setting.findOne({'contain.text': domain}, {'contain.$.domain': 1}, (err, setting: ISettingModel) => {
        if (err) {
          reject(err);
        }
        resolve(setting);
      });
    });
  }

}

export default new DnsController();
